const rows = $input.first().json;
const doc = Array.isArray(rows) ? rows[0]?.data : rows?.data;
if (!doc) return [];
const tz = 'America/Monterrey';
const mañana = new Date(Date.now() + 24 * 3600 * 1000);
const key = mañana.toLocaleDateString('sv-SE', { timeZone: tz }); // yyyy-mm-dd
const sesiones = (doc.bookings ?? [])
  .filter(b => b.date === key && (b.status === 'confirmed' || b.status === 'pending'))
  .sort((a, b) => a.time.localeCompare(b.time));
if (sesiones.length === 0) return [];
const lineas = sesiones.map(b => `· ${b.time} ${b.clientName} — ${b.serviceName} (${b.duration}h${b.status === 'pending' ? ', SIN depósito' : ''})`);
const mensaje = [`📅 Mañana en el estudio (${sesiones.length} sesión${sesiones.length > 1 ? 'es' : ''}):`, ...lineas].join('\n');
return [{ json: { mensaje } }];
